{"code": "import os
from PIL import Image

# Check for corrupt images in the entire directory structure
train_dir = 'data_small/chest-xray-pneumonia/chest_xray/'
all_corrupt_files = []

for root, dirs, files in os.walk(train_dir):
    for file in files:
        if file.lower().endswith(('.png', '.jpg', '.jpeg')):
            filepath = os.path.join(root, file)
            try:
                with Image.open(filepath) as img:
                    img.verify()
                    # Verify sometimes doesn't close properly, reopen with a new handle
                    img = Image.open(filepath)
                    img.load()
            except Exception as e:
                all_corrupt_files.append(filepath)
                print(f"Corrupt file: {filepath} - Error: {str(e)[:50]}")

print(f"\nTotal corrupt files found: {len(all_corrupt_files)}")"}

