from PIL import Image

# Get all corrupt files in a list
train_dir = 'data_small/chest-xray-pneumonia/chest_xray/'
all_corrupt_files = []

for root, dirs, files in os.walk(train_dir):
    for file in files:
        if file.lower().endswith(('.png', '.jpg', '.jpeg')):
            filepath = os.path.join(root, file)
            try:
                with Image.open(filepath) as img:
                    img.verify()
                    img = Image.open(filepath)
                    img.load()
            except Exception as e:
                all_corrupt_files.append(filepath)

# Delete all corrupt files
deleted_count = 0
for filepath in all_corrupt_files:
    try:
        os.remove(filepath)
        deleted_count += 1
    except Exception as e:
        pass

print(f"Deleted {deleted_count} corrupt files out of {len(all_corrupt_files)} found")"}

